style.css:
@-moz-document domain("netflix.com"), domain("www.netflix.com") {
/* Set custom background */
    body {
        background: url("https://i.pinimg.com/736x/1e/26/e3/1e26e3d5b517797bb584c9c85cab8dd4.jpg") no-repeat center center fixed !important;
        background-size: cover !important;
    }

    /* Remove Netflix default background */
    .our-story-container, .default-ltr-cache-1wk40ve {
        background: none !important;
    }

    /* Darken UI for better readability */
    .pinning-header, .profile-gate-container, .nm-content-horizontal-row {
        background-color: rgba(0, 0, 0, 0.7) !important;
    }
}
